    if len(s)>300: s=s[-300:]
    nums=re.findall(r"(\-?[0-9\.\,]+)", s)
    for x in reversed(nums):
        if x not in ("", "."):
            return x.replace(",","")
    return None

for s in [1,10,20,30,40,50,60]:
    rows=[json.loads(l) for l in open(f'results/run60/rollouts/{s}.jsonl')]
    n_correct=0; pred_in_q=0; correct_in_q=0; n_nums=[]
    distinct_sets={}
    for r in rows:
        q=r['input'].split('user\n',1)[1].rsplit(' Let\'s think step by step',1)[0]
        pred=last_number(r['output'])
        qnums=set(x.replace(',','') for x in re.findall(r"\-?[0-9\.\,]+", q))
        if pred in qnums: pred_in_q+=1
        if r['score']==1:
            n_correct+=1
            if pred in qnums: correct_in_q+=1
        n_nums.append(len(re.findall(r"\-?[0-9\.\,]+", r['output'])))
    print(f"step {s:2d}: correct={n_correct}/{len(rows)} ({n_correct/len(rows):.3f}) pred_copied_from_q={pred_in_q/len(rows):.2%} correct_and_in_q={correct_in_q/max(n_correct,1):.2%} nums_per_resp={sum(n_nums)/len(n_nums):.1f}")
EOF

