def last_number(s):
    if len(s)>300: s=s[-300:]
    nums=re.findall(r"(\-?[0-9\.\,]+)", s)
    for x in reversed(nums):
        if x not in ("", "."):
            return x.replace(",","")
    return None
tr=pd.read_parquet('raw/gsm8k/main/train-00000-of-00001.parquet')
