import json, re
def last_number(s, clip=True):
    if clip and len(s)>300: s=s[-300:]
    nums=re.findall(r"(\-?[0-9\.\,]+)", s)
    for x in reversed(nums):
        if x not in ("", "."):
            return x.replace(",","")
    return None
def analyze(path, label):
    rows=[json.loads(l) for l in open(path)]
    n=len(rows)
    gt_in_resp=0; gt_in_last300=0; gt_earlier_but_lastnum_diff=0; score1=0
    for r in rows:
        gt=r['gts']; out=r['output']
        if r['score']==1: score1+=1
        appears = gt in re.findall(r"\-?[0-9\.\,]+", out)
        if appears:
            gt_in_resp+=1
            if gt in re.findall(r"\-?[0-9\.\,]+", out[-300:]): gt_in_last300+=1
            if last_number(out,True)!=gt and last_number(out,False)==gt:
                gt_earlier_but_lastnum_diff+=1
    print(f"{label}: n={n} score1={score1} ({score1/n:.3f}) gt_appears_anywhere={gt_in_resp/n:.3f} gt_in_last300={gt_in_last300/n:.3f} lastnum(whole)==gt_but_lastnum(last300)!=gt: {gt_earlier_but_lastnum_diff/n:.3f}")
for s in [0,60]:
    analyze(f'results/run60/val_generations/{s}.jsonl', f'val step{s}')
for s in [1,60]:
    analyze(f'results/run60/rollouts/{s}.jsonl', f'train step{s}')
